import os
import uuid
import time
import json
import asyncio
from alchemystai import AlchemystAI

async def main():
    api_key = os.environ.get("ALCHEMYST_AI_API_KEY")
    run_id = os.environ.get("ZEALT_RUN_ID")

    if not api_key:
        print("Error: ALCHEMYST_AI_API_KEY not set")
        return
    if not run_id:
        print("Error: ZEALT_RUN_ID not set")
        return

    client = AlchemystAI(api_key=api_key)
    group_name = ["syllabus", "math101", run_id]

    # 1. Prepare 5 syllabus excerpts
    excerpts = [
        {
            "content": "The midterm exam will take place on October 15 during regular class hours.",
            "metadata": {"file_name": f"syllabus-{uuid.uuid4()}.md", "group_name": group_name}
        },
        {
            "content": "The required textbook for this course is 'Calculus' by James Stewart, 8th Edition.",
            "metadata": {"file_name": f"syllabus-{uuid.uuid4()}.md", "group_name": group_name}
        },
        {
            "content": "The grading policy is as follows: Homework 30%, Midterm 30%, Final Exam 40%.",
            "metadata": {"file_name": f"syllabus-{uuid.uuid4()}.md", "group_name": group_name}
        },
        {
            "content": "Office hours are Tuesdays and Thursdays from 2:00 PM to 4:00 PM in Room 302.",
            "metadata": {"file_name": f"syllabus-{uuid.uuid4()}.md", "group_name": group_name}
        },
        {
            "content": "Math 101: Introduction to Calculus. This course covers limits, derivatives, and integrals.",
            "metadata": {"file_name": f"syllabus-{uuid.uuid4()}.md", "group_name": group_name}
        }
    ]

    # 2. Ingest documents
    print("Ingesting documents...")
    for excerpt in excerpts:
        client.v1.context.add(
            documents=[{
                "content": excerpt["content"],
                "metadata": excerpt["metadata"]
            }],
            context_type="resource",
            source="syllabus",
            scope="internal"
        )

    # Allow time for indexing
    print("Waiting for indexing...")
    time.sleep(5)

    # 3. Parallel Search
    questions = [
        "When is the midterm?",
        "What textbook is required?",
        "What is the grading policy?"
    ]

    async def search_question(question):
        print(f"Searching for: {question}")
        # client.v1.context.search is likely synchronous in the current SDK version,
        # so we use asyncio.to_thread to run them in parallel.
        result = await asyncio.to_thread(
            client.v1.context.search,
            query=question,
            metadata={"group_name": group_name},
            similarity_threshold=0.5
        )

        snippet = ""
        if result and hasattr(result, 'contexts') and result.contexts:
            # Result is likely an object with a contexts attribute
            snippet = result.contexts[0].content
        elif isinstance(result, dict) and 'contexts' in result and result['contexts']:
            snippet = result['contexts'][0].get('content', "")

        return {"question": question, "snippet": snippet}

    print("Executing parallel searches...")
    tasks = [search_question(q) for q in questions]
    answers = await asyncio.gather(*tasks)

    # 4. Write results
    output = {
        "run_id": run_id,
        "answers": answers
    }

    output_path = "/workspace/syllabus_answers.json"
    with open(output_path, "w") as f:
        json.dump(output, f, indent=2)

    print(f"Results written to {output_path}")

if __name__ == "__main__":
    asyncio.run(main())

